  "Nothing to undo.": { ca: "No hi ha res per desfer.", es: "No hay nada que deshacer." },
  "Solo: only {a} (and the other soloed tracks) is evaluated.": { ca: "Solo: només s'avalua {a} (i els altres tracks en Solo).", es: "Solo: solo se evalúa {a} (y los otros tracks en Solo)." },
  "{a} muted.": { ca: "{a} silenciat.", es: "{a} silenciado." },
  "In Tweak Mode only the tweaked action can be edited: press Tab to leave it.": { ca: "En Tweak Mode només es pot editar l'acció en edició: prem Tab per sortir-ne.", es: "En Tweak Mode solo se puede editar la acción en edición: pulsa Tab para salir." },
  "Not possible in Tweak Mode: press Tab to leave it first.": { ca: "No es pot fer en Tweak Mode: primer prem Tab per sortir-ne.", es: "No se puede hacer en Tweak Mode: primero pulsa Tab para salir." },
  "Select a strip first.": { ca: "Primer selecciona un strip.", es: "Primero selecciona un strip." },
